/// Freezes inference to exactly one model for benchmark attribution.
///
/// This mode deliberately bypasses ADR 0150 specialist selection and fallback so a
/// benchmark result can never be attributed to a model that did not perform the work.
pub(crate) fn configured_benchmark_single_model(config: NativeModelConfig) -> Self {
    let routing = ModelRoutingPolicy::derive(config.clone(), Vec::new(), &[]);
    Self::new(
        Box::new(ConfiguredModelBackend(config.clone())),
        config,
        routing,
        HarnessPolicy::default(),
        true,
    )
}
